/*
 * A133442  3-Limiting word of the morphism 1->368, 2->457, 3->168, 4->257,
 *          5->247, 6->138, 7->245, 8->136.
 * https://oeis.org/A133442
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, less
 * Formula:   not stated
 * Range:     u8 n <= 87, u16 n <= 87, u32 n <= 87, u64 n <= 87, u128 n <= 87,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* A133442: nth symbol of the infinite word generated by the morphism
 * 1→368, 2→457, 3→168, 4→257, 5→247, 6→138, 7→245, 8→136
 * starting with the letter 3.  The symbol at position n (1‑indexed)
 * is obtained by decomposing n−1 into base‑3 digits and following
 * the appropriate branch in the morphism tree. */
#include <stdint.h>

seq_t a(idx_t n)
{
    /* Mapping table: each letter maps to a 3‑letter word.
       mapping[letter][digit] gives the child for the given digit. */
    static const seq_t mapping[9][3] = {
        {0, 0, 0},          /* 0 – unused                                          */
        {3, 6, 8},          /* 1 → 368                                              */
        {4, 5, 7},          /* 2 → 457                                              */
        {1, 6, 8},          /* 3 → 168                                              */
        {2, 5, 7},          /* 4 → 257                                              */
        {2, 4, 7},          /* 5 → 247                                              */
        {1, 3, 8},          /* 6 → 138                                              */
        {2, 4, 5},          /* 7 → 245                                              */
        {1, 3, 6}           /* 8 → 136                                              */
    };

    /* Convert n−1 to base‑3 digits (least significant first). */
    idx_t rem = n - 1;
    int stack[64];
    int top = 0;

    while (rem > 0) {
        stack[top++] = rem % 3;
        rem /= 3;
    }

    /* Traverse the morphism tree following the digits from most
       significant to least. */
    seq_t current = 3;               /* initial letter                                  */
    for (int i = top - 1; i >= 0; --i) {
        current = mapping[(int)current][stack[i]];
    }
    return current;
}
